-- Migration 0015 — Phase 5: transactional-outbox consumer correctness
-- (gap register D10).
--
-- Generated by `drizzle-kit generate` from src/schema/outbox-events.ts; the
-- header and the two data-backfill UPDATEs before the CHECK constraint were
-- added by hand.
--
-- Adds the columns the outbox consumer needs for a correct lease/claim:
--   claimed_at      when the CURRENT owner claimed (or renewed) the row —
--                   stale-row rescue keys off this, never created_at
--   claim_token     fences complete()/fail() to the current owner
--   attempts        claims so far; a row that keeps crashing its worker
--                   reaches 'dead' instead of being rescued forever
--   next_attempt_at retry backoff for a failed attempt
--   dead_at / replay_count   dead-letter bookkeeping + operator replay audit
--   updated_at
--
-- Backfill (existing data is never deleted):
--   * 'failed' rows were a terminal state that NOTHING ever retried (D10).
--     They become 'dead' — a visible, listable, replayable dead letter.
--   * 'processing' rows have no claim time. That includes rows stranded by the
--     old claimBatch, which flipped EVERY pending row to 'processing' but
--     returned only `batchLimit` of them. They get claimed_at = now(), so the
--     new rescue path requeues them one staleness window after this migration
--     (an old-version worker that is genuinely mid-flight during a rolling
--     deploy still has that window to finish).
--   * Any other unexpected status is preserved as a 'dead' letter (with the
--     original status recorded in `error`) rather than failing the migration
--     on the CHECK constraint or silently re-running it.
--
-- NOTE ON THE JOURNAL TIMESTAMP: drizzle-kit stamped this entry with the
-- wall-clock time, which is EARLIER than 0014's hand-set "when"
-- (1792000000000); drizzle-orm's migrator skips a migration whose "when" is
-- not newer than the last one applied, so _journal.json was set to
-- 1792100000000 — the same trap and fix as migrations 0013 and 0014.

ALTER TABLE "outbox_events" ADD COLUMN "attempts" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "outbox_events" ADD COLUMN "claimed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "outbox_events" ADD COLUMN "claim_token" uuid;--> statement-breakpoint
ALTER TABLE "outbox_events" ADD COLUMN "next_attempt_at" timestamp with time zone DEFAULT now() NOT NULL;--> statement-breakpoint
ALTER TABLE "outbox_events" ADD COLUMN "dead_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "outbox_events" ADD COLUMN "replay_count" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "outbox_events" ADD COLUMN "updated_at" timestamp with time zone DEFAULT now() NOT NULL;--> statement-breakpoint
CREATE INDEX "idx_outbox_pending_due" ON "outbox_events" USING btree ("next_attempt_at","created_at") WHERE "outbox_events"."status" = 'pending';--> statement-breakpoint
CREATE INDEX "idx_outbox_processing_claimed" ON "outbox_events" USING btree ("claimed_at") WHERE "outbox_events"."status" = 'processing';--> statement-breakpoint
CREATE INDEX "idx_outbox_dead" ON "outbox_events" USING btree ("dead_at") WHERE "outbox_events"."status" = 'dead';--> statement-breakpoint
UPDATE "outbox_events" SET "status" = 'dead', "dead_at" = now(), "updated_at" = now() WHERE "status" = 'failed';--> statement-breakpoint
UPDATE "outbox_events" SET "claimed_at" = now(), "updated_at" = now() WHERE "status" = 'processing' AND "claimed_at" IS NULL;--> statement-breakpoint
UPDATE "outbox_events" SET "status" = 'dead', "dead_at" = now(), "updated_at" = now(), "error" = 'migration 0015: unexpected legacy status ' || quote_literal("status") || COALESCE('; last error: ' || "error", '') WHERE "status" NOT IN ('pending', 'processing', 'completed', 'failed', 'dead');--> statement-breakpoint
ALTER TABLE "outbox_events" ADD CONSTRAINT "chk_outbox_status" CHECK ("outbox_events"."status" IN ('pending', 'processing', 'completed', 'dead'));